<div class="table-wrap"><table><thead><tr><th>Trip</th><th>City</th><th>Country</th><th>Action</th></tr></thead><tbody><?php foreach ($stops as $stop): ?><tr><td><?php echo h($stop['trip_name']); ?></td><td><?php echo h($stop['city']); ?></td><td><?php echo h((string)$stop['country']); ?></td><td><form method="post"><input type="hidden" name="action" value="delete_stop"><input type="hidden" name="id" value="<?php echo $stop['id']; ?>"><button class="danger" type="submit">Remove</button></form></td></tr><?php endforeach; ?></tbody></table></div>
